
const IMG={"bud": "data:image/webp;base64,", "lotus": "data:image/webp;base64,", "vA": "data:image/webp;base64,", "vB": "data:image/webp;base64,", "bR": "data:image/webp;base64,", "bL": "data:image/webp;base64,", "paper": "data:image/webp;base64,", "roller": "data:image/webp;base64,", "corner": "data:image/webp;base64,", "bg": "data:image/webp;base64,"};
Object.assign(IMG,{"bud":"data:image/webp;base64,","lotus":"data:image/webp;base64,","vA":"data:image/webp;base64,","vB":"data:image/webp;base64,","bL":"data:image/webp;base64,","bR":"data:image/webp;base64,"});
IMG.corner='./corner-updated.png';
const {useState,useEffect,useRef}=React,h=React.createElement;
const FLIP_BORDERS=1; // set to -1 to mirror the two side vines
const clamp=(x,a=0,b=1)=>Math.min(b,Math.max(a,x));
const E={io:t=>t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2,out:t=>1-Math.pow(1-t,3),back:t=>t<=0?0:1+2.4*Math.pow(t-1,3)+1.4*Math.pow(t-1,2),lin:t=>t};
